import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import { courseUrl, lessonUrl } from '../../common/api';
import ProgressBar from './ProgressBar';
import { duration, t } from './util';

/** One course in a grid: cover, title, summary, facts and, for its students, progress. */
export default class CourseCard extends Component {
  view() {
    const course = this.attrs.course;
    const me = course.me;
    const href = me && me.lastLessonId && !me.completedAt ? lessonUrl(course, {
      id: me.lastLessonId
    }) : courseUrl(course);
    return m("article", {
      className: 'SyllabusCard' + (course.status === 'draft' ? ' SyllabusCard--draft' : '')
    }, m(Link, {
      href: courseUrl(course),
      className: "SyllabusCard-cover",
      "aria-hidden": "true",
      tabindex: "-1"
    }, course.coverUrl ? m("img", {
      src: course.coverUrl,
      alt: "",
      loading: "lazy"
    }) : m(Icon, {
      name: "fas fa-chalkboard-user"
    })), m("div", {
      className: "SyllabusCard-body"
    }, m("div", {
      className: "SyllabusCard-badges"
    }, course.status === 'draft' ? m("span", {
      className: "SyllabusBadge SyllabusBadge--draft"
    }, t('course.draft')) : null, course.featured ? m("span", {
      className: "SyllabusBadge SyllabusBadge--featured"
    }, t('course.featured')) : null, course.access === 'groups' ? m("span", {
      className: "SyllabusBadge"
    }, m(Icon, {
      name: "fas fa-lock"
    }), " ", t('course.restricted')) : null, course.category ? m("span", {
      className: "SyllabusBadge SyllabusBadge--category"
    }, course.category.name) : null), m("h3", {
      className: "SyllabusCard-title"
    }, m(Link, {
      href: courseUrl(course)
    }, course.title)), course.summary ? m("p", {
      className: "SyllabusCard-summary"
    }, course.summary) : null, m("ul", {
      className: "SyllabusFacts"
    }, m("li", null, m(Icon, {
      name: "fas fa-list-ol"
    }), " ", t('course.lessons', {
      count: course.lessonCount
    })), course.difficulty ? m("li", null, t('difficulty.' + course.difficulty)) : null, course.estimatedMinutes ? m("li", null, m(Icon, {
      name: "far fa-clock"
    }), " ", duration(course.estimatedMinutes)) : null, course.instructor ? m("li", null, t('course.by', {
      name: course.instructor.displayName
    })) : null), me ? m("div", {
      className: "SyllabusCard-progress"
    }, m(ProgressBar, {
      percent: me.completedAt ? 100 : me.percent,
      compact: true
    }), m(Link, {
      className: "Button Button--link SyllabusCard-continue",
      href: href
    }, me.completedAt ? t('course.completed') : me.done ? t('course.continue') : t('course.start'))) : null));
  }
}
flarum.reg.add('ernestdefoe-syllabus', 'forum/components/CourseCard', CourseCard);